Item.method_code:
if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefReloadCapturedGet|" + aml);
}
var selected = this.node;
this.setProperty("name", "Before reload");
this.loadAML("<Item type='RefCapturedRecord' action='get'><name>Current document</name></Item>");
selected.SelectSingleNode("name").InnerText = "Captured value";
return this.getInnovator().newResult("Ignored response");

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefInspectCapturedGet|" + aml);
}
if (this.getProperty("name") != "Current document")
{
    throw new Exception("The later binding did not receive the reloaded document");
}
this.setProperty("name", "Ignored document value");
return this.getInnovator().newResult("Another ignored response");
